#include <stdio.h>

int main(void) {
    int x;
    long long sum = 0;
    int count = 0;
    while (scanf("%d", &x) == 1) {
        sum += x;
        count++;
    }
    if (count == 0) {
        printf("нет данных\n");
    } else {
        printf("%d %.2f\n", count, (double)sum / count);
    }
    return 0;
}

