#include <stdio.h>

int main(void) {
    int x;
    int even = 0, odd = 0;
    while (scanf("%d", &x) == 1) {
        if (x % 2 == 0) {
            even++;
        } else {
            odd++;
        }
    }
    printf("%d %d\n", even, odd);
    return 0;
}

