#include <stdio.h>

int main(void) {
    long long prev, x;
    long long best = 0;
    if (scanf("%lld", &prev) == 1) {
        while (scanf("%lld", &x) == 1) {
            long long diff = x - prev;
            if (diff < 0) {
                diff = -diff;
            }
            if (diff > best) {
                best = diff;
            }
            prev = x;
        }
    }
    printf("%lld\n", best);
    return 0;
}

